// Compiles the Rust statistics kernels (native/stats) to WebAssembly and embeds the module in src/shared/stats-wasm.ts,
// which the main process, its insights worker, the renderer and the browser preview all load. The generated file is
// committed, so a machine without Rust can still build: it then checks that the file came from the current sources.
const { spawnSync } = require('node:child_process');
const { createHash } = require('node:crypto');
const { existsSync, readFileSync, writeFileSync } = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const crate = path.join(root, 'native/stats');
const generated = path.join(root, 'src/shared/stats-wasm.ts');
const wasm = path.join(crate, 'target/wasm32-unknown-unknown/release/focus_guide_stats.wasm');

// Line endings are normalized so a Windows checkout with CRLF gives the same hash.
const hash = createHash('sha256');
for (const file of ['Cargo.toml', 'Cargo.lock', 'src/lib.rs']) hash.update(file).update(readFileSync(path.join(crate, file), 'utf8').replace(/\r\n/g, '\n'));
const source = hash.digest('hex').slice(0, 16);
const committed = existsSync(generated) ? /STATS_WASM_SOURCE = '([0-9a-f]+)'/.exec(readFileSync(generated, 'utf8'))?.[1] : undefined;

const cargo = process.env.FOCUS_GUIDE_CARGO || 'cargo';
const probe = spawnSync(cargo, ['--version'], { windowsHide: true, encoding: 'utf8' });
if (probe.error || probe.status !== 0) {
  if (committed === source) { console.log('Rust is not installed; using the committed statistics module, which matches native/stats.'); process.exit(0); }
  throw new Error('native/stats changed and Rust is needed to rebuild it. Install rustup, run "rustup target add wasm32-unknown-unknown", or set FOCUS_GUIDE_CARGO.');
}
const result = spawnSync(cargo, ['build', '--release', '--locked', '--target', 'wasm32-unknown-unknown'], { cwd: crate, windowsHide: true, stdio: 'inherit' });
if (result.error) throw result.error;
if (result.status !== 0) {
  // Cargo without the wasm32 target (rustup installs only the host target) still builds the app from a matching committed module.
  if (committed === source) { console.warn('Cargo could not build the statistics module; using the committed one, which matches native/stats. To rebuild it, run "rustup target add wasm32-unknown-unknown".'); process.exit(0); }
  console.error('If the wasm32 target is missing, run "rustup target add wasm32-unknown-unknown".'); process.exit(result.status ?? 1);
}
const bytes = readFileSync(wasm);
writeFileSync(generated, `// Generated by scripts/build-stats.cjs from native/stats (${bytes.length} bytes of WebAssembly). Do not edit.\n`
  + `export const STATS_WASM_SOURCE = '${source}';\nexport const STATS_WASM = '${bytes.toString('base64')}';\n`);
console.log(`Statistics module built (${bytes.length} bytes, source ${source}).`);
